class HitCounter
{
    queue<int> hits;
    void expire(int timestamp)
    {
        while (!hits.empty() && timestamp - hits.front() >= 300)
        {
            hits.pop();
        }
    }
public:
    HitCounter() {}
    void hit(int timestamp)
    {
        expire(timestamp);
        hits.push(timestamp);
    }
    int getHits(int timestamp)
    {
        expire(timestamp);
        return hits.size();
    }
};
